import"./Nav.astro_astro_type_script_index_0_lang.7b87a28f.js";const l=document.getElementById("register-form"),r=document.getElementById("register-error"),t=document.getElementById("register-submit"),u=document.getElementById("reg-name"),d=document.getElementById("reg-phone"),g=document.getElementById("reg-city"),p=document.getElementById("reg-pass"),I=document.getElementById("reg-pass2");function e(n){r.textContent=n,r.classList.add("is-visible"),t.disabled=!1,t.textContent="إنشاء الحساب ←"}l.addEventListener("submit",async n=>{n.preventDefault(),r.classList.remove("is-visible"),t.disabled=!0,t.textContent="جاري إنشاء الحساب...",await new Promise(s=>setTimeout(s,800));const o=u.value.trim(),i=d.value.trim(),c=g.value,a=p.value,m=I.value;if(o.length<2){e("يرجى إدخال الاسم بالكامل.");return}if(i.length<8){e("يرجى إدخال رقم جوال صحيح.");return}if(!c){e("يرجى اختيار المدينة.");return}if(a.length<4){e("كلمة المرور يجب ألا تقل عن 4 أحرف.");return}if(a!==m){e("كلمتا المرور غير متطابقتين.");return}try{const s={name:o,phone:i,city:c,role:"customer",createdAt:new Date().toISOString(),loginAt:new Date().toISOString()};localStorage.setItem("wslha_user",JSON.stringify(s))}catch{}window.location.href="/orders"});
